360	    // Rendered rows may still await XML, or retain an older poll. Finish uses
361	    // one fresh complete native snapshot, then keeps those exact targets even
362	    // when the successful lock changes later snapshots to status=locked.
363	    return defer(() => current() ? this.bs.getSessionsMonitor(group).pipe(
364	      take(1),
365	      switchMap(rows => {
366	        if (!current()) return EMPTY;
367	        const unlocked = rows.filter(row => BigInt(row.testId) > 0n &&
368	          !TestSessionUtil.hasState(row.testState, 'status', 'locked'));
369	        const lockIds = unlocked.map(row => row.testId);
370	        const pending = new Set(this.bs.pendingFinishTargets(group));
371	        const eligible = rows.filter(row => BigInt(row.testId) > 0n &&
372	          !TestSessionUtil.hasState(row.testState, 'status', 'pending') &&
373	          !TestSessionUtil.hasState(row.testState, 'CONTROLLER', 'TERMINATED'));
374	        const remaining = new Set(eligible.map(row => row.testId));
375	        for (const id of pending) if (!remaining.has(id)) pending.delete(id);
376	        const terminateIds = eligible.filter(row => pending.has(row.testId) ||
377	          (!TestSessionUtil.hasState(row.testState, 'status', 'locked') &&
378	            (TestSessionUtil.hasState(row.testState, 'CONNECTION', 'POLLING') ||
379	              TestSessionUtil.hasState(row.testState, 'CONNECTION', 'WEBSOCKET'))))
380	          .map(row => row.testId);
381	        // Retain before writing: even an error/abort can follow a committed
382	        // lock. A retry uses a fresh snapshot without adopting unrelated locks.
383	        terminateIds.forEach(id => pending.add(id));
384	        this.bs.rememberFinishTargets(group, [...pending]);
385	        return this.bs.lock(group, lockIds).pipe(
386	          delay(1500),
387	          mergeMap(() => current() ? this.bs.command('terminate', ['lock'], terminateIds) : EMPTY),
388	          tap(() => {
389	            if (current()) this.bs.rememberFinishTargets(group,
390	              this.bs.pendingFinishTargets(group).filter(id => !terminateIds.includes(id)));
391	          })
392	        );
393	      }),
394	      takeUntil(this.disconnected$),
395	      takeUntil(fromEvent(scope, 'abort'))
396	    ) : EMPTY);
397	  }
