399	  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
400	    return sessions
401	      .sort((session1, session2) => {
402	        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
403	        if (sort.active === 'timestamp') {
404	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
405	        }
406	        if (sort.active === '_checked') {
407	          const session1isChecked = this.isChecked(session1);
408	          const session2isChecked = this.isChecked(session2);
409	          if (!session1isChecked && session2isChecked) {
410	            return 1 * sortDirectionFactor;
411	          }
412	          if (session1isChecked && !session2isChecked) {
413	            return -1 * sortDirectionFactor;
414	          }
415	          return 0;
416	        }
417	        if (sort.active === '_superState') {
418	          return (TestSessionsSuperStates.indexOf(session1.state) -
419	            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
420	        }
421	        if (sort.active === '_currentBlock') {
422	          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
423	          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
424	          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
425	        }
426	        if (sort.active === '_currentUnit') {
427	          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
428	          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
429	          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
430	        }
431	        if (sort.active.startsWith('bookletState:')) {
432	          const bookletState = sort.active.replace('bookletState:', '');
433	          const label = (session: TestSession): string =>
434	            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
435	          const a = label(session1);
436	          const b = label(session2);
437	          return a.localeCompare(b) * sortDirectionFactor;
438	        }
439	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
440	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
441	        if (typeof valA === 'number') {
442	          valA = valA.toString(10);
443	        }
444	        if (typeof valB === 'number') {
445	          valB = valB.toString(10);
446	        }
447	        if ((typeof valA === 'object') || (typeof valB === 'object')) {
448	          return 0;
449	        }
450	        return valA.localeCompare(valB) * sortDirectionFactor;
451	      });
452	  }
