522	  getMaxTimeAcrossAllSessions(selected: Selected): number {
523	    const sessions = this.sessions;
524	    let lowestTime: number = 0;
525	    sessions.forEach(session => {
526	      let maxTime;
527	      if ('units' in session.booklet) {
528	        const blocks = session.booklet.units.children.filter(testletOrUnit => testletOrUnit.id === selected.element?.id
529	        );
530	        if (blocks.length > 0 && 'restrictions' in blocks[0]) {
531	          maxTime = blocks[0].restrictions.timeMax?.minutes;
532	        }
533	      }
534	      if (maxTime && lowestTime === 0) {
535	        lowestTime = maxTime;
536	      }
537	      if (maxTime && maxTime < lowestTime) {
538	        lowestTime = maxTime;
539	      }
540	    });
541	
542	    return lowestTime;
543	  }
