545	  private static groupForGoto(sessionsSet: TestSession[], selection: Selected): GotoCommandData {
546	    const groupedByTargetUnitAlias: GotoCommandData = {};
547	    sessionsSet.forEach(session => {
548	      if (!session.data.bookletName || !isBooklet(session.booklet)) return;
549	
550	      const ignoreTestlet = (testlet: Testlet) => !!testlet.restrictions.show &&
551	        !!session.bookletStates &&
552	        (session.bookletStates[testlet.restrictions.show.if] !== testlet.restrictions.show.is);
553	      const firstUnit = selection.element?.blockId ?
554	        BookletUtil.getFirstUnitOfBlock(selection.element.blockId, session.booklet, ignoreTestlet) :
555	        null;
556	      if (!firstUnit) return;
557	
558	      if (!Object.keys(groupedByTargetUnitAlias).includes(firstUnit.alias)) {
559	        groupedByTargetUnitAlias[firstUnit.alias] = { ids: [session.data.testId], isClosed: undefined };
560	      } else {
561	        groupedByTargetUnitAlias[firstUnit.alias].ids.push(session.data.testId);
562	      }
563	
564	      if (session.timeLeft && selection.element && Object.keys(session.timeLeft).includes(selection.element.id)) {
565	        groupedByTargetUnitAlias[firstUnit.alias].isClosed = true;
566	      }
567	    });
568	    return groupedByTargetUnitAlias;
569	  }
