585	  private static getSessionSetStats(sessionSet: TestSession[], all: number = sessionSet.length): TestSessionSetStat {
586	    const booklets = new Set();
587	    const bookletSpecies = new Set();
588	    const bookletStateLabels: { [key: string]: string } = {};
589	    let paused = 0;
590	    let locked = 0;
591	
592	    sessionSet
593	      .forEach(session => {
594	        booklets.add(session.data.bookletName);
595	        bookletSpecies.add(session.booklet.species);
596	        Object.values(isBooklet(session.booklet) ? session.booklet?.states : {})
597	          .forEach(state => {
598	            bookletStateLabels[state.id] = state.label;
599	          });
600	        if (TestSessionUtil.isPaused(session)) paused += 1;
601	        if (TestSessionUtil.isLocked(session)) locked += 1;
602	      });
603	
604	    return {
605	      numberOfSessions: sessionSet.length,
606	      differentBooklets: booklets.size,
607	      differentBookletSpecies: bookletSpecies.size,
608	      allChecked: (all === sessionSet.length),
609	      bookletStateLabels,
610	      pausedSessions: paused,
611	      lockedSessions: locked
612	    };
613	  }
