+      [answerAt, progressAt, presentationAt, pageAt, pagesAt].every(clock) &&
+      progressAt >= answerAt && presentationAt >= answerAt &&
+      pageAt >= Math.max(progressAt, presentationAt) && pagesAt >= Math.max(progressAt, presentationAt);
+  } catch {return false;}
+}

